import { canonicalize } from './canonical.js';
import type { CredentialDescriptor, IdentityVersionDescriptor, LineageLink } from './entities.js';
import { CanonicalizationError } from './errors.js';
import type { DeepReadonly } from './ownership.js';
import type { JsonValue } from './primitives.js';
import { sha256Hex } from './sha256.js';

type JsonObject = { [key: string]: JsonValue };

function assertNoPresentUndefined(value: unknown, path: string, seen: WeakSet<object>): void {
  if (value === null || typeof value !== 'object') {
    return;
  }
  if (seen.has(value)) {
    return;
  }
  seen.add(value);

  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i += 1) {
      if (!(i in value)) {
        throw new CanonicalizationError(`${path}[${i}] is a hole`);
      }
      const item: unknown = value[i];
      if (item === undefined) {
        throw new CanonicalizationError(`${path}[${i}] is present but undefined`);
      }
      assertNoPresentUndefined(item, `${path}[${i}]`, seen);
    }
    seen.delete(value);
    return;
  }

  for (const key of Object.keys(value)) {
    const item = (value as Record<string, unknown>)[key];
    if (item === undefined) {
      throw new CanonicalizationError(`${path}.${key} is present but undefined`);
    }
    assertNoPresentUndefined(item, `${path}.${key}`, seen);
  }
  seen.delete(value);
}

