// Version schemes for UIA-CORE-001 §3.2.
//
// SEMVER_2 follows Semantic Versioning 2.0.0 strictly.
// CONTENT_HASH and OPAQUE_TAG have only the normative rule "non-empty":
// A-7 (CONTENT_HASH label format) remains OPEN, and OPAQUE_TAG has no ordering
// semantics. Nothing here infers a format, digest length, or version order for
// those schemes.

import type { VersionScheme } from './entities.js';
import type { Result } from './errors.js';
import { mechanismFailure } from './errors.js';
import { hasLoneSurrogate } from './primitives.js';

export interface VersionLabel {
  readonly scheme: VersionScheme;
  readonly label: string;
}

export interface SemVer {
  /** Original label text; exact selectors compare this, not the parsed fields. */
  readonly text: string;
  /** Decimal digit strings without leading zeros, compared without Number precision loss. */
  readonly major: string;
  readonly minor: string;
  readonly patch: string;
  readonly prerelease: readonly string[];
  readonly build: readonly string[];
}

const VERSION_SCHEMES: readonly VersionScheme[] = ['SEMVER_2', 'CONTENT_HASH', 'OPAQUE_TAG'];

const NUMERIC_IDENTIFIER = /^(0|[1-9]\d*)$/;
const DIGITS = /^\d+$/;
const ALPHANUMERIC_IDENTIFIER = /^[0-9A-Za-z-]+$/;
const BUILD_IDENTIFIER = /^[0-9A-Za-z-]+$/;

export function isVersionScheme(value: unknown): value is VersionScheme {
  return typeof value === 'string' && (VERSION_SCHEMES as readonly string[]).includes(value);
}

function invalidLabel(message: string): Result<never> {
  return { ok: false, error: mechanismFailure('E_VERSION_LABEL_INVALID', message) };
}

/**
 * Validates a version label for a given scheme and returns an owned, frozen
 * label record. The label is preserved verbatim: no trimming, normalization,
 * or format inference.
 */
export function validateVersionLabel(value: unknown, scheme: VersionScheme): Result<VersionLabel> {
  if (!isVersionScheme(scheme)) {
    return invalidLabel(`Unknown version scheme: ${String(scheme)}`);
  }
  if (typeof value !== 'string') {
    return invalidLabel('Version label must be a string');
  }
  if (hasLoneSurrogate(value)) {
    return invalidLabel('Version label must not contain lone surrogates');
  }

  if (scheme === 'SEMVER_2') {
    if (parseSemVer(value) === undefined) {
      return invalidLabel(`Invalid SemVer 2.0.0 label: ${JSON.stringify(value)}`);
    }
  } else if (value.length === 0) {
    return invalidLabel('Version label must not be empty');
  }

  return { ok: true, value: Object.freeze({ scheme, label: value }) };
}

/**
 * Strict Semantic Versioning 2.0.0 parser. Returns `undefined` for any input
 * that does not match the official grammar.
 */
export function parseSemVer(text: string): SemVer | undefined {
  const plusIndex = text.indexOf('+');
  const buildPart = plusIndex === -1 ? undefined : text.slice(plusIndex + 1);
  const coreAndPrerelease = plusIndex === -1 ? text : text.slice(0, plusIndex);

  if (buildPart !== undefined) {
    if (buildPart.length === 0 || buildPart.includes('+') || !buildIdentifiersValid(buildPart)) {
      return undefined;
    }
  }

  const dashIndex = coreAndPrerelease.indexOf('-');
  const prereleasePart = dashIndex === -1 ? undefined : coreAndPrerelease.slice(dashIndex + 1);
  const core = dashIndex === -1 ? coreAndPrerelease : coreAndPrerelease.slice(0, dashIndex);

  if (prereleasePart !== undefined && (prereleasePart.length === 0 || !prereleaseIdentifiersValid(prereleasePart))) {
    return undefined;
  }

  const coreParts = core.split('.');
  if (coreParts.length !== 3) {
    return undefined;
  }
  const [major, minor, patch] = coreParts;
  if (!NUMERIC_IDENTIFIER.test(major) || !NUMERIC_IDENTIFIER.test(minor) || !NUMERIC_IDENTIFIER.test(patch)) {
    return undefined;
  }

  return Object.freeze({
    text,
    major,
    minor,
    patch,
    prerelease: Object.freeze(prereleasePart === undefined ? [] : prereleasePart.split('.')),
    build: Object.freeze(buildPart === undefined ? [] : buildPart.split('.')),
  });
}

function prereleaseIdentifiersValid(value: string): boolean {
  for (const identifier of value.split('.')) {
    if (identifier.length === 0) {
      return false;
    }
    if (DIGITS.test(identifier)) {
      if (!NUMERIC_IDENTIFIER.test(identifier)) {
        return false;
      }
    } else if (!ALPHANUMERIC_IDENTIFIER.test(identifier)) {
      return false;
    }
  }
  return true;
}

function buildIdentifiersValid(value: string): boolean {
  for (const identifier of value.split('.')) {
    if (identifier.length === 0 || !BUILD_IDENTIFIER.test(identifier)) {
      return false;
    }
  }
  return true;
}

/** Compares two decimal digit strings (no leading zeros) without Number precision loss. */
function compareNumericIdentifiers(a: string, b: string): -1 | 0 | 1 {
  if (a.length !== b.length) {
    return a.length < b.length ? -1 : 1;
  }
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

function comparePrereleaseIdentifiers(a: string, b: string): -1 | 0 | 1 {
  const aNumeric = DIGITS.test(a);
  const bNumeric = DIGITS.test(b);

  if (aNumeric && bNumeric) {
    return compareNumericIdentifiers(a, b);
  }
  if (aNumeric) {
    return -1;
  }
  if (bNumeric) {
    return 1;
  }
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

function comparePrerelease(a: readonly string[], b: readonly string[]): -1 | 0 | 1 {
  if (a.length === 0 && b.length === 0) {
    return 0;
  }
  if (a.length === 0) {
    return 1;
  }
  if (b.length === 0) {
    return -1;
  }

  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) {
    const order = comparePrereleaseIdentifiers(a[i], b[i]);
    if (order !== 0) {
      return order;
    }
  }
  if (a.length === b.length) {
    return 0;
  }
  return a.length < b.length ? -1 : 1;
}

/**
 * SemVer 2.0.0 precedence. Build metadata is deliberately ignored, as the
 * specification requires.
 */
export function compareSemVer(a: SemVer, b: SemVer): -1 | 0 | 1 {
  const majorOrder = compareNumericIdentifiers(a.major, b.major);
  if (majorOrder !== 0) return majorOrder;

  const minorOrder = compareNumericIdentifiers(a.minor, b.minor);
  if (minorOrder !== 0) return minorOrder;

  const patchOrder = compareNumericIdentifiers(a.patch, b.patch);
  if (patchOrder !== 0) return patchOrder;

  return comparePrerelease(a.prerelease, b.prerelease);
}

/**
 * Exact decimal-string increment. Used for `^` and `~` upper bounds; it never
 * converts a numeric identifier to a JavaScript number, so an "unsafe"
 * increment cannot occur and no bound is silently truncated.
 */
export function incrementDecimal(value: string): string {
  const digits = value.split('');
  let index = digits.length - 1;

  while (index >= 0 && digits[index] === '9') {
    digits[index] = '0';
    index -= 1;
  }
  if (index < 0) {
    return `1${digits.join('')}`;
  }
  digits[index] = String(Number(digits[index]) + 1);
  return digits.join('');
}

// Versioned selector mechanism for UIA-CORE-001 §8.2.
//
// This grammar is an implementation mechanism, NOT normative protocol
// semantics (plan ambiguity A-1). Its version label is
// `uia-ref-selector@1`; any assessment or documentation quoting the grammar
// must identify it by that label.
//
// Supported forms: `=x`, `*`, and `&&`-joined comparators `> >= < <= ^ ~`.
// Range selectors are incompatible with CONTENT_HASH and OPAQUE_TAG and are
// reported as a MechanismFailure with S_SELECTOR_INCOMPATIBLE_SCHEME.

import type { VersionScheme } from './entities.js';
import type { Result } from './errors.js';
import { mechanismFailure } from './errors.js';
import { deepFreeze } from './ownership.js';
import { hasLoneSurrogate } from './primitives.js';
import {
  compareSemVer,
  incrementDecimal,
  isVersionScheme,
  parseSemVer,
  type SemVer,
  type VersionLabel,
} from './version-scheme.js';

export const SELECTOR_MECHANISM_VERSION = 'uia-ref-selector@1' as const;

export type SelectorOperator = '=' | '>' | '>=' | '<' | '<=' | '^' | '~';

export interface SelectorComparator {
  readonly op: SelectorOperator;
  /** Version text for SEMVER_2, or the exact label text for the other schemes. */
  readonly text: string;
  /** Parsed form; present for SEMVER_2 comparators and absent for exact opaque labels. */
  readonly version?: SemVer;
}

export interface CompiledSelector {
  readonly mechanism: typeof SELECTOR_MECHANISM_VERSION;
  readonly scheme: VersionScheme;
  readonly kind: 'WILDCARD' | 'COMPARATORS';
  readonly comparators: readonly SelectorComparator[];
}

const OPERATORS: readonly SelectorOperator[] = ['>=', '<=', '=', '>', '<', '^', '~'];

const RANGE_OPERATORS: readonly SelectorOperator[] = ['>', '>=', '<', '<=', '^', '~'];

function syntaxFailure(message: string): Result<never> {
  return { ok: false, error: mechanismFailure('E_SELECTOR_SYNTAX_INVALID', message) };
}

function incompatibleScheme(message: string): Result<never> {
  return { ok: false, error: mechanismFailure('S_SELECTOR_INCOMPATIBLE_SCHEME', message) };
}

function freezeSelector(selector: CompiledSelector): CompiledSelector {
  return deepFreeze(selector);
}

function splitOperator(segment: string): { readonly op: SelectorOperator; readonly operand: string } | undefined {
  for (const op of OPERATORS) {
    if (segment.startsWith(op)) {
      return { op, operand: segment.slice(op.length) };
    }
  }
  return undefined;
}

function upperBoundText(op: '^' | '~', version: SemVer): string {
  if (op === '~') {
    return `${version.major}.${incrementDecimal(version.minor)}.0`;
  }
  if (version.major !== '0') {
    return `${incrementDecimal(version.major)}.0.0`;
  }
  if (version.minor !== '0') {
    return `0.${incrementDecimal(version.minor)}.0`;
  }
  return `0.0.${incrementDecimal(version.patch)}`;
}

function expandRange(op: '^' | '~', version: SemVer): Result<readonly SelectorComparator[]> {
  const upperText = upperBoundText(op, version);
  const upper = parseSemVer(upperText);
  if (upper === undefined) {
    return syntaxFailure(`Cannot compute a valid ${op} upper bound for ${version.text}`);
  }

  return {
    ok: true,
    value: [
      { op: '>=', text: version.text, version },
      { op: '<', text: upperText, version: upper },
    ],
  };
}

function parseComparatorSegment(
  segment: string,
  scheme: VersionScheme,
): Result<readonly SelectorComparator[]> {
  const split = splitOperator(segment);
  if (split === undefined) {
    return syntaxFailure(`Selector segment must start with an operator: ${JSON.stringify(segment)}`);
  }
  const { op, operand } = split;

  if (operand.length === 0) {
    return syntaxFailure(`Selector operator ${op} requires an operand`);
  }
  if (/\s/.test(operand)) {
    return syntaxFailure(`Selector operand must not contain whitespace: ${JSON.stringify(operand)}`);
  }

  if (scheme !== 'SEMVER_2') {
    if (RANGE_OPERATORS.includes(op)) {
      return incompatibleScheme(`Selector ${op} is not compatible with ${scheme}; only exact match and wildcard are supported`);
    }
    return { ok: true, value: [{ op: '=', text: operand }] };
  }

  const version = parseSemVer(operand);
  if (version === undefined) {
    return syntaxFailure(`Selector operand is not a SemVer 2.0.0 version: ${JSON.stringify(operand)}`);
  }

  if (op === '^' || op === '~') {
    return expandRange(op, version);
  }

  return { ok: true, value: [{ op, text: operand, version }] };
}

/**
 * Parses and validates a selector expression for a given version scheme.
 * The result is a frozen, owned record; parsing is separate from matching.
 */
export function compileSelector(value: unknown, scheme: VersionScheme): Result<CompiledSelector> {
  if (!isVersionScheme(scheme)) {
    return syntaxFailure(`Unknown version scheme: ${String(scheme)}`);
  }
  if (typeof value !== 'string') {
    return syntaxFailure('Selector must be a string');
  }
  if (hasLoneSurrogate(value)) {
    return syntaxFailure('Selector must not contain lone surrogates');
  }

  const expression = value.trim();
  if (expression.length === 0) {
    return syntaxFailure('Selector must not be empty');
  }

  if (expression === '*') {
    return {
      ok: true,
      value: freezeSelector({
        mechanism: SELECTOR_MECHANISM_VERSION,
        scheme,
        kind: 'WILDCARD',
        comparators: [],
      }),
    };
  }

  const segments = expression.split('&&').map((segment) => segment.trim());
  if (segments.some((segment) => segment.length === 0)) {
    return syntaxFailure('Selector must not contain empty && segments');
  }

  const comparators: SelectorComparator[] = [];
  for (const segment of segments) {
    const parsed = parseComparatorSegment(segment, scheme);
    if (!parsed.ok) {
      return parsed;
    }
    comparators.push(...parsed.value);
  }

  if (scheme !== 'SEMVER_2' && (comparators.length !== 1 || comparators[0].op !== '=')) {
    return incompatibleScheme(`${scheme} supports only exact match and wildcard selectors`);
  }

  return {
    ok: true,
    value: freezeSelector({
      mechanism: SELECTOR_MECHANISM_VERSION,
      scheme,
      kind: 'COMPARATORS',
      comparators,
    }),
  };
}

function matchesComparator(comparator: SelectorComparator, labelVersion: SemVer, labelText: string): boolean {
  if (comparator.op === '=') {
    return labelText === comparator.text;
  }
  if (comparator.version === undefined) {
    return false;
  }

  const order = compareSemVer(labelVersion, comparator.version);
  switch (comparator.op) {
    case '>':
      return order > 0;
    case '>=':
      return order >= 0;
    case '<':
      return order < 0;
    case '<=':
      return order <= 0;
    default:
      // `^` and `~` are expanded during compilation and never reach matching.
      return false;
  }
}

/**
 * Evaluates a compiled selector against a validated label.
 *
 * Returns `false` for a scheme mismatch rather than matching across schemes.
 * Exact (`=`) comparison is full string identity, including build metadata;
 * all other operators use SemVer precedence, which ignores build metadata.
 */
export function selectorMatches(selector: CompiledSelector, label: VersionLabel): boolean {
  if (selector.scheme !== label.scheme) {
    return false;
  }
  if (selector.kind === 'WILDCARD') {
    return true;
  }

  if (selector.scheme !== 'SEMVER_2') {
    const exact = selector.comparators[0];
    return exact !== undefined && exact.op === '=' && label.label === exact.text;
  }

  const labelVersion = parseSemVer(label.label);
  if (labelVersion === undefined) {
    return false;
  }

  for (const comparator of selector.comparators) {
    if (!matchesComparator(comparator, labelVersion, label.label)) {
      return false;
    }
  }
  return true;
}

