  for (const candidate of selected) {
    const core = coreById.get(candidate.assessment_id);
    if (
      core === undefined ||
      seen.has(core.assessment_id) ||
      !appliesToEdge(candidate, edge) ||
      !appliesToEdge(core, edge)
    ) {
      continue;
    }
    seen.add(core.assessment_id);
    accepted.push(core);
  }

  return accepted;
}

