import type { ContinuityAssessment, ContinuityAssuranceRequirement, Policy } from '../../src/core/assessment.js';
import type { LineageRelationType } from '../../src/core/entities.js';
import type { TemporalContext } from '../../src/core/temporal.js';
import type { ConditionalVersionBinding, LineageTraversalScope, Path } from '../../src/core/traversal.js';
import {
  assessmentId,
  domainId,
  identityVersionId,
  participantId,
  timestamp,
} from '../../src/core/primitives.js';

export const BASE_TIME = 1_700_000_000_000;

export const CTX: TemporalContext = {
  basis: 'ASSESSED_AT',
  declared: {},
  trust: {},
};

export const EMPTY_POLICY: Policy = {};

export function assessmentRecord(input: {
  readonly id: string;
  readonly subject: string;
  readonly parents: readonly string[];
  readonly relation: LineageRelationType;
  readonly verified?: readonly string[];
  readonly unverified?: readonly string[];
  readonly by?: string;
}): ContinuityAssessment {
  return {
    assessment_id: assessmentId(input.id),
    subject_version_id: identityVersionId(input.subject),
    parent_version_ids: input.parents.map((parent) => identityVersionId(parent)),
    declared_relation: input.relation,
    assessment_profile_ref: 'profile-1',
    assessment_method_version: '1.0.0',
    verified_claims: input.verified ?? [],
    unverified_claims: input.unverified ?? [],
    evidence_refs: [],
    assessed_by: domainId(input.by ?? 'domain-a'),
    assessed_at: timestamp(BASE_TIME),
  };
}

export function requirementFor(
  claims: readonly string[],
  trusted: readonly string[] = ['domain-a'],
): ContinuityAssuranceRequirement {
  return {
    required_claims: claims,
    trusted_assessors: trusted.map((domain) => domainId(domain)),
  };
}

export function bindingFor(input: {
  readonly origin: string;
  readonly selector: string;
  readonly scope: LineageTraversalScope;
  readonly claims: readonly string[];
  readonly targetParticipant?: string;
  readonly trusted?: readonly string[];
}): ConditionalVersionBinding {
  return {
    target_participant_id: participantId(input.targetParticipant ?? 'participant-a'),
    origin_version_id: identityVersionId(input.origin),
    selector_expression: input.selector,
    traversal_scope: input.scope,
    assurance_requirement: requirementFor(input.claims, input.trusted),
  };
}

export function pathNodes(path: Path): string[] {
  const nodes: string[] = [String(path.edges[0].child)];
  for (const edge of path.edges) {
    nodes.push(String(edge.parent));
  }
  return nodes;
}

import { describe, expect, test } from 'bun:test';
import { buildLineageGraph } from '../../src/core/lineage.js';
import { evaluateBinding } from '../../src/core/traversal.js';
import { identityVersionId } from '../../src/core/primitives.js';
import { descriptor, link, participant, registry } from '../support/fixtures.js';
import { CTX, EMPTY_POLICY, assessmentRecord, bindingFor, pathNodes } from '../support/traversal.js';

const alice = participant('participant-a');

function chainState() {
  const origin = descriptor({ id: 'iv-a-1', participant: 'participant-a', versionLabel: '1.0.0' });
  const candidate = descriptor({
    id: 'iv-a-2',
    participant: 'participant-a',
    versionLabel: '1.1.0',
    lineage: [link('iv-a-1', 'CONTINUATION')],
  });
  const graph = buildLineageGraph(registry([alice], [origin, candidate]));
  return { origin, candidate, graph, descriptors: [origin, candidate] };
}

function stateSnapshot(state: { descriptors: readonly unknown[]; graph: unknown }): string {
  return JSON.stringify({ descriptors: state.descriptors, graph: state.graph });
}

describe('§12 Category B: conditional binding and traversal (Task 9 subset)', () => {
  test('B-1 exact anchoring rejects an otherwise bindable candidate', () => {
    const { candidate, graph, descriptors } = chainState();
    const state = { graph, descriptors, assessments: [] };
    const binding = bindingFor({
      origin: 'iv-a-1',
      selector: '=1.0.0',
      scope: 'CONTINUATION_ONLY',
      claims: [],
    });
    const before = stateSnapshot(state);

    const result = evaluateBinding(state, binding, identityVersionId('iv-a-2'), EMPTY_POLICY, CTX);

    expect(result).toEqual({
      eligible: false,
      code: 'ERR_AUTHORITY_BINDING_MISMATCH',
      details: {},
    });
    expect(stateSnapshot(state)).toBe(before);
    expect(candidate.id).toBe(identityVersionId('iv-a-2'));
    expect(JSON.stringify(state).toLowerCase()).not.toContain('grant');
  });

  test('B-2 an unsatisfied required claim keeps the version and declaration intact', () => {
    const { candidate, graph, descriptors } = chainState();
    const assessment = assessmentRecord({
      id: 'a-1',
      subject: 'iv-a-2',
      parents: ['iv-a-1'],
      relation: 'CONTINUATION',
      verified: ['PARENT_SIGNATURE_MATCH'],
    });
    const state = { graph, descriptors, assessments: [assessment] };
    const binding = bindingFor({
      origin: 'iv-a-1',
      selector: '>=1.0.0',
      scope: 'CONTINUATION_ONLY',
      claims: ['PARENT_SIGNATURE_MATCH', 'GOVERNANCE_REVIEWED'],
    });
    const before = stateSnapshot(state);
    const candidateBefore = JSON.stringify(candidate);

    const result = evaluateBinding(state, binding, identityVersionId('iv-a-2'), EMPTY_POLICY, CTX);

    expect(result.eligible).toBe(false);
    if (result.eligible) return;
    expect('code' in result).toBe(true);
    if (!('code' in result)) return;
    expect(result.code).toBe('ERR_ASSURANCE_PREDICATE_UNSATISFIED');
    expect(result.details.perPath).toHaveLength(1);
    const outcome = result.details.perPath?.[0].outcome;
    expect(outcome?.status).toBe('INVALID');
    if (outcome?.status !== 'INVALID') return;
    expect(outcome.missing).toEqual(['GOVERNANCE_REVIEWED']);
    expect(outcome.disallowed).toEqual([]);

    expect(stateSnapshot(state)).toBe(before);
    expect(JSON.stringify(candidate)).toBe(candidateBefore);
  });

  test('B-3 diamond lineage yields both valid paths without authority artifacts', () => {
    const bob = participant('participant-b');
    const dave = participant('participant-d');
    const a = descriptor({ id: 'iv-a-1', participant: 'participant-a', versionLabel: '1.0.0' });
    const b = descriptor({
      id: 'iv-b',
      participant: 'participant-b',
      versionLabel: '1.0.0',
      lineage: [link('iv-a-1', 'FORKED_FROM')],
    });
    const c = descriptor({
      id: 'iv-c',
      participant: 'participant-a',
      versionLabel: '1.0.0',
      lineage: [link('iv-a-1', 'CONTINUATION')],
    });
    const d = descriptor({
      id: 'iv-d',
      participant: 'participant-d',
      versionLabel: '2.0.0',
      lineage: [link('iv-b', 'MERGED_FROM'), link('iv-c', 'MERGED_FROM')],
    });
    const graph = buildLineageGraph(registry([alice, bob, dave], [a, b, c, d]));
    const assessments = [
      assessmentRecord({ id: 'a-db', subject: 'iv-d', parents: ['iv-b'], relation: 'MERGED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-dc', subject: 'iv-d', parents: ['iv-c'], relation: 'MERGED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-ba', subject: 'iv-b', parents: ['iv-a-1'], relation: 'FORKED_FROM', verified: ['CONT_OK'] }),
      assessmentRecord({ id: 'a-ca', subject: 'iv-c', parents: ['iv-a-1'], relation: 'CONTINUATION', verified: ['CONT_OK'] }),
    ];
    const state = { graph, descriptors: [a, b, c, d], assessments };
    const binding = bindingFor({
      origin: 'iv-a-1',
      selector: '>=1.0.0',
      scope: 'FULL_ANCESTRY',
      claims: ['CONT_OK'],
      targetParticipant: 'participant-d',
    });
    const before = stateSnapshot(state);

    const result = evaluateBinding(state, binding, identityVersionId('iv-d'), EMPTY_POLICY, CTX);

    expect(result.eligible).toBe(true);
    if (!result.eligible) return;
    expect(result.acceptedPaths.map(pathNodes)).toEqual([
      ['iv-d', 'iv-b', 'iv-a-1'],
      ['iv-d', 'iv-c', 'iv-a-1'],
    ]);
    expect(stateSnapshot(state)).toBe(before);
    expect(JSON.stringify(state).toLowerCase()).not.toContain('grant');
  });
});

